@startuml

class Gym {
  + ComputeMonthlyBalance(month : date) : int
  + ComputeAnnualBalance(year : int) : int
  + SendArrearsReminders()
  + SendMedicalCheckReminders()
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + startDate : date
}

class MonthlySubscription extends Subscription {
}

class AnnualSubscription extends Subscription {
}

class Service {
  + name : string
  + additionalCost : double
}

class WorkoutPlan {
  + weeklyVisits : int
}

class WorkoutPlanExercise {
  + repetitions : int
  + frequency : string
}

class Exercise {
  + name : string
}

class MedicalCheckResult {
  + weight : double
  + bodyFat : double
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
}

Customer "1" -- "*" Subscription
Subscription "0..*" -- "1" Gym
Subscription "1" -- "*" Service : includes
Subscription "1" -- "*" Service : additional

Customer "1" -- "1" WorkoutPlan
WorkoutPlan "1" -- "*" WorkoutPlanExercise
WorkoutPlanExercise "0..*" -- "1" Exercise
WorkoutPlan "0..*" -- "0..*" Service : takes into account

Customer "1" -- "0..*" MedicalCheckResult
MedicalStaff "1" -- "*" MedicalCheckResult
MedicalStaff "1" -- "0..*" Customer : assists

@enduml

